{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "The closest retrieved analogue, a phenylthio benzimidazole carbamate, has approximately 30% oral bioavailability in humans, directly exceeding the 20% threshold and supporting high F for this thioether-containing heteroaromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Vismodegib, an aryl amide/pyridine drug, has an absolute oral bioavailability of 31.8% in humans after a 150 mg oral dose, supporting F >= 20% for the query's amide/heteroaromatic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Belumosudil, which contains an indazole/heteroaromatic amide motif, has 64% absolute oral bioavailability in healthy subjects after a 200 mg oral dose, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Sorafenib, a close N-methylpyridinecarboxamide diaryl ether/urea drug, has approximately 50% absolute oral bioavailability under fasted conditions, matching the query's fasted condition and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A conflicting sorafenib report gives approximately 8.5% oral bioavailability in humans, which would be below the threshold; however, this is outweighed by multiple other sorafenib absolute-bioavailability estimates of 38-50% and has lower structural transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable human absolute-bioavailability evidence (30-100%) supports F >= 20%; the only sub-threshold value (sorafenib 8.5%) is an outlier contradicted by multiple other sorafenib estimates and has low transferability.",
  "evidence_gaps": [
    "No direct pharmacokinetic data are available for the query molecule.",
    "All retrieved analogues have low Morgan similarity (<0.26), limiting structural transferability.",
    "Sorafenib bioavailability estimates conflict (8.5% vs 38-50%), introducing uncertainty.",
    "Fasted-state absolute bioavailability data are limited mainly to sorafenib among the analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

